func (m WorkspaceScanStartingMsg) Transition() jobs.Transition {
	// The cancel goes with the state that says the work started, which is the
	// only moment there is anything to stop (D7).
	return jobs.Transition{
		Kind: jobs.KindScan, Target: m.RepoPath,
		State: jobs.ItemRunning, Cancel: m.Cancel,
	}
}

func (m WorkspaceScanCompleteMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindScan, Target: m.RepoPath, State: jobs.ItemDone}
	if m.Error != nil {
		t.State = jobs.ItemFailed
		t.Detail = "scan failed — check logs"
	}
	return t
}

func (m WorkspaceSyncStartingMsg) Transition() jobs.Transition {
	return jobs.Transition{Kind: jobs.KindSync, Target: m.RepoPath, State: jobs.ItemRunning}
}

func (m WorkspaceSyncCompleteMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindSync, Target: m.RepoPath, State: jobs.ItemDone}
	switch {
	case m.Error != nil:
		t.State = jobs.ItemFailed
		t.Detail = "sync failed — check logs"
	case m.Outcome == git.SyncSkipped:
		// A refusal is not a failure: the fetch happened, the merge did not,
		// and the reason is what the summary names one repository by.
		t.State = jobs.ItemSkipped
		t.Detail = m.Reason
	case m.Outcome == git.SyncUpdated:
		t.Detail = syncDetailUpdated
	}
	return t
}

func (m EntryDeletedMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindDelete, Target: m.Path, State: jobs.ItemDone}
	if m.Error != nil {
		t.State = jobs.ItemFailed
		t.Detail = "delete failed — check logs"
	}
	return t
}

// Compile-time proof that every progress message this view emits can be applied
// to the registry. A message added without one would be routed, would update
// the view, and would leave its row spinning for the life of the view — which
		}
	}
	return out
}

// ── What each message tells the registry (jobs.Reporter) ─────────────────────

func (m InventoryScanStartingMsg) Transition() jobs.Transition {
	return jobs.Transition{Kind: jobs.KindScan, Target: m.Name, State: jobs.ItemRunning, Cancel: m.Cancel}
}

func (m InventoryScanFinishedMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindScan, Target: m.Name, State: jobs.ItemDone}
	if m.Err != nil {
		t.State = jobs.ItemFailed
		t.Detail = "scan failed — check logs"
	}
	return t
}

// D10: rescanCmd had no starting message at all — only a finished one — so its
// items would have jumped straight from queued to done and the distinction
// between the two would have been decorative here.
var (
	_ jobs.Reporter = InventoryScanStartingMsg{}
	_ jobs.Reporter = InventoryScanFinishedMsg{}
}

// ── What each message tells the registry (jobs.Reporter) ─────────────────────

func (m ImageScanStartingMsg) Transition() jobs.Transition {
	return jobs.Transition{Kind: jobs.KindScan, Target: m.ImageName, State: jobs.ItemRunning, Cancel: m.Cancel}
}

func (m ImageScanFinishedMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindScan, Target: m.ImageName, State: jobs.ItemDone}
	if m.Err != nil {
		t.State = jobs.ItemFailed
		t.Detail = "scan failed — check logs"
	}
	return t
}

func (m RegistryPullStartingMsg) Transition() jobs.Transition {
	return jobs.Transition{Kind: jobs.KindPull, Target: m.ImageName, State: jobs.ItemRunning, Cancel: m.Cancel}
}

func (m RegistryPullCompleteMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindPull, Target: m.ImageName, State: jobs.ItemDone}
	switch {
	case len(m.InUse) > 0:
		t.State = jobs.ItemFailed
		t.Detail = "not updated — the image is in use"
	case isBlocked(m.Err):
		// The reason, not "check logs": it names the rule, and it is what an
		// agent that asked for the pull reads (§3.82).
		t.State = jobs.ItemFailed
		t.Detail = "refused — " + m.Err.Error()
	case m.Err != nil:
		t.State = jobs.ItemFailed
		t.Detail = "pull failed — check logs"
	}
	return t
}

// Compile-time proof that every progress message can be applied. One added
// without a transition would leave its row spinning for the life of the view.
package jobsview

import (
	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// The glyph vocabulary of both tables. One table, five states, and the two
// levels share it: a run that failed and the target that failed it read the
// same, which is what makes → feel like opening the row rather than arriving
// somewhere else.
//
// They are glyphs the application already has. A sixth codepoint for "queued"
// when IconPending is the clock the pipeline column already uses would be a
// second name for one idea (see the note on IconLock in theme/icons.go).

// runStateGlyph is the run's state, or the shared spinner frame while it goes.
//
// Queued spins too. It is waiting on a worker rather than on nothing, the
// difference is in the State column, and a static clock next to a row whose
// counter is climbing reads as a stall.
func runStateGlyph(r runRow) string {
	switch r.Run.State() {
	case jobs.RunRunning, jobs.RunQueued:
		return r.Frame
	case jobs.RunFailed:
		return theme.IconError
	case jobs.RunCancelled:
		return theme.IconCanceled
	default:
		return theme.IconOK
	}
}

// itemStateGlyph is the same for one target. An item that is queued does not
// spin: within a run, waiting for a worker is exactly what distinguishes it
// from the ones that are running, and that is the D6 distinction this level
// exists to show.
func itemStateGlyph(r itemRow) string {
	switch r.Item.State {
	case jobs.ItemRunning:
		return r.Frame
	case jobs.ItemQueued:
		return theme.IconPending
	case jobs.ItemFailed:
		return theme.IconError
	case jobs.ItemSkipped:
		return theme.IconSkipped
	default:
		return theme.IconOK
	}
}

// runStateStyle colours a run.
//
// `done` gets the same green as every other success glyph in the application
// (Rule 121, theme.StatusOKStyle) — the status view colours "OK" the same
// way, and a jobs list is exactly the kind of screen where a reader scans for
// the one row that is not green. `failed` is what deserves to be found
// without reading. `cancelled` is a warning rather than an error: nothing
// broke, the user stopped it. `queued` is dim, the way a zero and a
// placeholder are: nothing has happened yet.
//
// `running` is left plain on purpose. The spinner in the glyph column already
// says it, it says it by moving, and a second answer in colour would be one
// more thing to keep in step.
func runStateStyle(state jobs.RunState) lipgloss.Style {
	switch state {
	case jobs.RunDone:
		return theme.StatusOKStyle
	case jobs.RunFailed:
		return theme.StatusErrorStyle
	case jobs.RunCancelled:
		return theme.StatusWarningStyle
	case jobs.RunQueued:
		return theme.DimStyle
	default:
		return lipgloss.NewStyle()
	}
}

// itemStateStyle is the same table one level down. `skipped` joins the warning
// side: a sync refused on a dirty tree did not fail, and the reason is in the
// Detail column beside it.
func itemStateStyle(state jobs.ItemState) lipgloss.Style {
	switch state {
	case jobs.ItemDone:
		return theme.StatusOKStyle
	case jobs.ItemFailed:
		return theme.StatusErrorStyle
	case jobs.ItemSkipped:
		return theme.StatusWarningStyle
	case jobs.ItemQueued:
		return theme.DimStyle
	default:
		return lipgloss.NewStyle()
	}
}

